using AutoMapper;using TaskMonitoringApp.Models.DTOs;using TaskMonitoringApp.Models.Entities;using TaskMonitoringApp.Models.Enums;using TaskMonitoringApp.Models.Repositories;using TaskMonitoringApp.Models.Services;using TodoMonitoringApp.Models.Entities;namespace TaskMonitoringApp.Models.Business{    public class TodoServices(ITodoRepository repository, IMapper mapper) : ITodoServices    {        private readonly ITodoRepository _repository = repository;        private readonly IMapper _mapper = mapper;        public async Task AddNewTodo(string UserId, TodoDTO todo)        {            if (todo.Task == null)            {                throw new ArgumentNullException("Missing {TaskID} while creating the new Todo.");            }            await _repository.AddTodoAsync(UserId, _mapper.Map<Todo>(todo));        }        public async Task DeleteTodoById(string UserId, int id)        {            var getTodo = await _repository.GetTodoByIdAsync<Todo>(UserId, id, ResponseDataMode.Model);            getTodo.IsDeleted = true;            getTodo.DeletedOn = DateTime.Now;            await _repository.UpdateTodoAsync(UserId, getTodo);        }        public async Task<IEnumerable<TodoDTOWithTaskDTO>> GetAllTodo(string UserId, Status status)        {            return await _repository.GetAllTodoAsync<TodoDTOWithTaskDTO>(UserId, status, ResponseDataMode.ModelDTO);        }        public async Task<IEnumerable<TodoDTOWithTaskDTO>> GetAllTodo(string UserId, Status status, DateTime selectDate)        {            if (selectDate.Date == DateTime.Today.Date)            {                return await _repository.GetAllTodoAsync<TodoDTOWithTaskDTO>(UserId, status, ResponseDataMode.ModelDTO);            }            return await _repository.GetAllTodoAsync<TodoDTOWithTaskDTO>(UserId, status, selectDate, ResponseDataMode.ModelDTO);        }        public async Task<IEnumerable<TodoDTOWithTaskDTO>> GetAllTodo(string UserId)        {            return await _repository.GetAllTodoAsync<TodoDTOWithTaskDTO>(UserId, Status.All, ResponseDataMode.ModelDTO);        }        public async Task<IEnumerable<TodoDTOWithTaskDTO>> GetAllTodo(string UserId, int taskId, Status status)        {            return await _repository.GetAllTodoAsync<TodoDTOWithTaskDTO>(UserId, taskId, status,  ResponseDataMode.ModelDTO);        }        public async Task<IEnumerable<TodoDTOWithTaskDTO>> GetAllTodo(string UserId, int taskId, Status status, DateTime selectDate)        {            if (selectDate.Date == DateTime.Today.Date)            {                return await _repository.GetAllTodoAsync<TodoDTOWithTaskDTO>(UserId, taskId, status, ResponseDataMode.ModelDTO);            }            return await _repository.GetAllTodoAsync<TodoDTOWithTaskDTO>(UserId, taskId, status, selectDate, ResponseDataMode.ModelDTO);        }        public async Task<IEnumerable<TodoDTOWithTaskDTO>> GetAllTodo(string UserId, int taskId)        {            return await _repository.GetAllTodoAsync<TodoDTOWithTaskDTO>(UserId, taskId, Status.All, ResponseDataMode.ModelDTO);        }        public async Task<TodoDTO> GetTodoById(string UserId, int id)        {            return await _repository.GetTodoByIdAsync<TodoDTO>(UserId, id, ResponseDataMode.ModelDTO);        }        public async Task UpdateTodo(string userId, TodoDTO todo)        {            var todoToUpdate = await _repository.GetTodoByIdAsync<Todo>(userId, todo.Id, ResponseDataMode.Model);            _mapper.Map(todo, todoToUpdate);            await _repository.UpdateTodoAsync(userId, todoToUpdate);        }        public async Task<TodoProgressAnalysisDTO> GetTodoProgressAnalyses(string userId, DateTime forDate)        {            if(forDate.Date == DateTime.Now.Date)            {                return await _repository.GetTodoProgressAnalysesAsync<TodoProgressAnalysisDTO>(userId, ResponseDataMode.ModelDTO);            }            return await _repository.GetTodoProgressAnalysesAsync<TodoProgressAnalysisDTO>(userId, forDate, ResponseDataMode.ModelDTO);        }        public async Task<TodoProgressAnalysisDTO> GetTodoProgressAnalyses(string userId, int taskId)        {            return await _repository.GetTodoProgressAnalysesAsync(userId, taskId);        }        public async Task UpdateTodoStatus(string userId, int todoId, Status statusToChange)        {            await _repository.UpdateTodoStatusAsync(userId, todoId, statusToChange);        }        public async Task UpdateTodoNotes(string userId, int todoId, string notes)        {            await _repository.UpdateTodoNotesAsync(userId, todoId, notes);        }        public async Task AddBulkTodos(string userId, BulkTodoCreateDTO bulkDto)        {            bulkDto.UserId = userId;            await _repository.AddBulkTodosAsync(bulkDto);        }    }}